// Some portions generated by Claude
/** Export of the graph: its loaded statements as Turtle, the drawn graph as a standalone SVG image or as PNG. */
import { NODE_TEXT_LEFT } from "./graph-config.ts";
import { edgeLabelSize, graphNodePresentation, nodeCornerRadius } from "./graph-geometry.ts";
import type { EdgeCurve, EdgeLabelPlacement, Graph, GraphEdge, GraphNode } from "./graph-types.ts";
import { ARROW_MARKER, nodeVisual } from "./graph-visuals.ts";
import { sparqlTermFromNodeId } from "./rdf-terms.ts";

const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const XSD_STRING = "http://www.w3.org/2001/XMLSchema#string";

const PREFIXES: ReadonlyArray<readonly [string, string]> = [
  ["dcterms", "http://purl.org/dc/terms/"],
  ["foaf", "http://xmlns.com/foaf/0.1/"],
  ["geo", "http://www.w3.org/2003/01/geo/wgs84_pos#"],
  ["owl", "http://www.w3.org/2002/07/owl#"],
  ["prov", "http://www.w3.org/ns/prov#"],
  ["rdf", "http://www.w3.org/1999/02/22-rdf-syntax-ns#"],
  ["rdfs", "http://www.w3.org/2000/01/rdf-schema#"],
  ["schema", "http://schema.org/"],
  ["sh", "http://www.w3.org/ns/shacl#"],
  ["skos", "http://www.w3.org/2004/02/skos/core#"],
  ["xsd", "http://www.w3.org/2001/XMLSchema#"],
];

/** A local name every Turtle parser accepts (a strict subset of PN_LOCAL). */
const SIMPLE_LOCAL_NAME = /^[A-Za-z_][A-Za-z0-9_-]*$/;

function turtleString(value: string) {
  return `"${value.replace(/[\\"\n\r\t]/g, (character) => ({ "\\": "\\\\", '"': '\\"', "\n": "\\n", "\r": "\\r", "\t": "\\t" })[character]!)}"`;
}

function iriEscape(iri: string) {
  return iri.replace(/[\u0000- <>"{}|^`\\]/g, (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`);
}

/**
 * The loaded statements as Turtle 1.2: one block per subject, `a` for rdf:type, the usual prefixes where they fit,
 * and statements about statements with their triple terms (`<<( s p o )>>`).
 */
export function graphTurtle(graph: Graph) {
  const used = new Set<string>();
  const blankNodeLabels = new Map<string, string>();
  const iri = (value: string) => {
    for (const [prefix, namespace] of PREFIXES) {
      const local = value.slice(namespace.length);
      if (value.startsWith(namespace) && SIMPLE_LOCAL_NAME.test(local)) {
        used.add(prefix);
        return `${prefix}:${local}`;
      }
    }
    return `<${iriEscape(value)}>`;
  };
  const blankNodeLabel = (value: string) => {
    let label = blankNodeLabels.get(value);
    if (label === undefined) {
      label = `b${blankNodeLabels.size}`;
      blankNodeLabels.set(value, label);
    }
    return label;
  };
  const term = (nodeId: string): string | null => {
    const value = sparqlTermFromNodeId(nodeId);
    if (!value) return null;
    if (value.type === "uri") return iri(value.value);
    if (value.type === "bnode") return `_:${blankNodeLabel(nodeId)}`;
    const text = turtleString(value.value);
    if (value["xml:lang"]) return `${text}@${value["xml:lang"]}${value["its:dir"] ? `--${value["its:dir"]}` : ""}`;
    return value.datatype && value.datatype !== XSD_STRING ? `${text}^^${iri(value.datatype)}` : text;
  };

  const subjects = new Map<string, Map<string, Set<string>>>();
  for (const edge of graph.edges) {
    const subject = term(edge.source);
    const object = term(edge.target);
    if (!subject || !object || subject.startsWith('"')) continue;
    const predicate = edge.predicate === RDF_TYPE ? "a" : iri(edge.predicate);
    let predicates = subjects.get(subject);
    if (!predicates) subjects.set(subject, (predicates = new Map()));
    let objects = predicates.get(predicate);
    if (!objects) predicates.set(predicate, (objects = new Set()));
    objects.add(object);
  }
  // Statements about statements: the object is an RDF 1.2 triple term.
  for (const link of graph.statementLinks ?? []) {
    const subject = term(link.source);
    const statementSubject = term(link.subject);
    const statementObject = term(link.object);
    if (!subject || !statementSubject || !statementObject || subject.startsWith('"')) continue;
    const predicate = link.predicate === RDF_TYPE ? "a" : iri(link.predicate);
    const object = `<<( ${statementSubject} ${iri(link.statementPredicate)} ${statementObject} )>>`;
    let predicates = subjects.get(subject);
    if (!predicates) subjects.set(subject, (predicates = new Map()));
    let objects = predicates.get(predicate);
    if (!objects) predicates.set(predicate, (objects = new Set()));
    objects.add(object);
  }
  if (!subjects.size) return "";
  const byText = (left: string, right: string) => (left < right ? -1 : left > right ? 1 : 0);
  const predicateOrder = (left: string, right: string) =>
    Number(left !== "a") - Number(right !== "a") ||
    Number(left.startsWith("<")) - Number(right.startsWith("<")) ||
    byText(left, right);
  const blocks = [...subjects]
    .sort(([left], [right]) => byText(left, right))
    .map(
      ([subject, predicates]) =>
        `${subject} ${[...predicates]
          .sort(([left], [right]) => predicateOrder(left, right))
          .map(([predicate, objects]) => `${predicate} ${[...objects].sort(byText).join(", ")}`)
          .join(" ;\n    ")} .`,
    );
  const header = PREFIXES.filter(([prefix]) => used.has(prefix))
    .map(([prefix, namespace]) => `@prefix ${prefix}: <${namespace}> .`)
    .join("\n");
  return `${header ? `${header}\n\n` : ""}${blocks.join("\n\n")}\n`;
}

export type SvgPalette = {
  background: string;
  edge: string;
  nodeText: string;
  labelText: string;
  labelFill: string;
  font: string;
};

export type GraphSvgInput = {
  /** The drawn nodes, with positions. */
  nodes: readonly GraphNode[];
  edges: readonly GraphEdge[];
  curves: ReadonlyMap<string, EdgeCurve>;
  /** The edge labels the canvas shows. */
  labels: ReadonlyMap<string, EdgeLabelPlacement>;
  /** Resolves a colour the canvas takes from CSS (`var(--…)`) to a value a standalone file can use. */
  color: (value: string) => string;
  palette: SvgPalette;
  /** Statements about statements: dashed lines from a node to the middle of the statement's edge. */
  connectors?: readonly EdgeCurve[];
};

function xml(text: string) {
  return text.replace(/[&<>"]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[character]!);
}

const round = (value: number) => Math.round(value * 10) / 10;

/** The drawn graph as a standalone SVG document: every edge (also those the canvas draws with WebGL), framed. */
export function graphSvg({ nodes, edges, curves, labels, color, palette, connectors = [] }: GraphSvgInput) {
  const placed = nodes.filter((node) => node.x !== undefined && node.y !== undefined);
  const position = new Map(placed.map((node) => [node.id, { x: node.x!, y: node.y! }]));
  // Large graphs are drawn without curves; their edges are straight lines between the nodes.
  const pathOf = (edge: GraphEdge) => {
    const curve = curves.get(edge.id);
    if (curve) return curve.path;
    const source = position.get(edge.source);
    const target = position.get(edge.target);
    return source && target && edge.source !== edge.target
      ? `M${round(source.x)},${round(source.y)} L${round(target.x)},${round(target.y)}`
      : null;
  };
  const boxes = placed.map((node) => {
    const { width, height } = graphNodePresentation(node);
    return { node, width, height, x: node.x! - width / 2, y: node.y! - height / 2 };
  });
  const xs: number[] = [];
  const ys: number[] = [];
  for (const box of boxes) {
    xs.push(box.x, box.x + box.width);
    ys.push(box.y, box.y + box.height);
  }
  for (const edge of edges) {
    const curve = curves.get(edge.id);
    if (!curve) continue;
    for (const point of curve.points ?? [curve.start, curve.control, curve.end]) {
      xs.push(point.x);
      ys.push(point.y);
    }
  }
  const padding = 32;
  // Loops, not Math.min(...xs): a spread of 100,000+ arguments overflows the call stack.
  const extent = (values: number[]) =>
    values.reduce((range, value) => [Math.min(range[0], value), Math.max(range[1], value)], [Infinity, -Infinity]);
  const [lowX, highX] = xs.length ? extent(xs) : [0, 0];
  const [lowY, highY] = ys.length ? extent(ys) : [0, 0];
  const minX = lowX - padding;
  const minY = lowY - padding;
  const width = Math.max(1, highX + padding - minX);
  const height = Math.max(1, highY + padding - minY);
  const edgeColor = color(palette.edge);
  const parts = [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${round(minX)} ${round(minY)} ${round(width)} ${round(height)}" width="${Math.ceil(width)}" height="${Math.ceil(height)}">`,
    `<defs><marker id="arrow" markerWidth="${ARROW_MARKER.width}" markerHeight="${ARROW_MARKER.height}" refX="${ARROW_MARKER.refX}" refY="${ARROW_MARKER.refY}" orient="auto" markerUnits="strokeWidth"><path d="${ARROW_MARKER.path}" fill="${xml(edgeColor)}"/></marker></defs>`,
    `<rect x="${round(minX)}" y="${round(minY)}" width="${round(width)}" height="${round(height)}" fill="${xml(color(palette.background))}"/>`,
    `<g font-family="${xml(color(palette.font))}" font-size="12" font-weight="600">`,
  ];
  for (const edge of edges) {
    const path = pathOf(edge);
    if (path)
      parts.push(`<path d="${xml(path)}" fill="none" stroke="${xml(edgeColor)}" stroke-width="1.2" marker-end="url(#arrow)"/>`);
  }
  for (const connector of connectors) {
    parts.push(
      `<path d="${xml(connector.path)}" fill="none" stroke="${xml(edgeColor)}" stroke-width="1.2" stroke-dasharray="4 3"/>`,
      `<circle cx="${round(connector.end.x)}" cy="${round(connector.end.y)}" r="3.5" fill="${xml(color(palette.background))}" stroke="${xml(edgeColor)}" stroke-width="1.2"/>`,
    );
  }
  for (const edge of edges) {
    const placement = labels.get(edge.id);
    if (!placement || !curves.has(edge.id)) continue;
    const size = edgeLabelSize(edge);
    parts.push(
      `<rect x="${round(placement.point.x - size.width / 2)}" y="${round(placement.point.y - size.height / 2)}" width="${round(size.width)}" height="${round(size.height)}" rx="9" fill="${xml(color(palette.labelFill))}"/>`,
      `<text x="${round(placement.point.x)}" y="${round(placement.point.y)}" text-anchor="middle" dominant-baseline="central" font-size="11" fill="${xml(color(palette.labelText))}">${xml(size.label)}</text>`,
    );
  }
  for (const { node, width: boxWidth, height: boxHeight, x, y } of boxes) {
    const visual = nodeVisual(node);
    const { label } = graphNodePresentation(node);
    parts.push(
      `<g transform="translate(${round(x)} ${round(y)})">`,
      `<rect width="${round(boxWidth)}" height="${round(boxHeight)}" rx="${nodeCornerRadius(node)}" fill="${xml(color(visual.fill))}" stroke="${xml(color(visual.stroke))}" stroke-width="1.2"/>`,
      `<circle cx="17" cy="${round(boxHeight / 2)}" r="4" fill="${xml(color(visual.stroke))}"/>`,
      `<text x="${NODE_TEXT_LEFT}" y="${round(boxHeight / 2 + 4)}" fill="${xml(color(palette.nodeText))}">${xml(label)}</text>`,
      `</g>`,
    );
  }
  parts.push("</g>", "</svg>");
  return parts.join("\n");
}

/** Resolves `var(--name)` against an element's computed style; other values are returned as they are. */
export function cssColorResolver(element: Element) {
  const style = getComputedStyle(element);
  return (value: string) => {
    const variable = /^var\((--[\w-]+)\)$/.exec(value.trim());
    return variable ? style.getPropertyValue(variable[1]).trim() || "#888" : value;
  };
}

/** An SVG from graphSvg drawn onto a canvas at `scale` (less when the canvas would exceed what browsers allow), as PNG. */
export async function svgToPng(svg: string, scale = 2): Promise<Blob> {
  const width = Number(/ width="(\d+)"/.exec(svg)?.[1] ?? 1);
  const height = Number(/ height="(\d+)"/.exec(svg)?.[1] ?? 1);
  const fit = Math.min(scale, 16384 / Math.max(width, 1), 16384 / Math.max(height, 1), Math.sqrt(120_000_000 / Math.max(width * height, 1)));
  const url = URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" }));
  try {
    const image = new Image();
    image.decoding = "async";
    image.src = url;
    await image.decode();
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.floor(width * fit));
    canvas.height = Math.max(1, Math.floor(height * fit));
    const context = canvas.getContext("2d");
    if (!context) throw new Error("This browser cannot draw the image.");
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    return await new Promise<Blob>((resolve, reject) =>
      canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error("The image could not be created."))), "image/png"),
    );
  } finally {
    URL.revokeObjectURL(url);
  }
}

/** Saves a file through the browser's download. */
export function downloadFile(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.rel = "noopener";
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}
